function evRate(d){const n=d.cards.length;return n?Math.round(d.cards.filter(c=>lvl(c.src)>=2).length/n*100):0}
function bibOf(cards){const m=new Map();cards.forEach(c=>{if(c.src&&!c.src.own&&c.src.k!=="Wikipedia"&&c.src.t){const a=apaS(c.src);if(!m.has(a))m.set(a,c.src)}});
 return[...m.entries()].sort((a,b)=>a[0].localeCompare(b[0],S.lang)).map(x=>({apa:x[0],s:x[1]}))}

// ===================== توليد البطاقات من النص (بلا ذكاء اصطناعي خارجي) =====================
const STOP2=new Set(["this","that","with","from","which","their","there","have","been","were","also","such","into","than","more","other","these","those","about","between","using","used","while","where","when","what","will","would","could","should","only","some","many","most","each","both","very","often","الذي","التي","الذين","هذا","هذه","ذلك","حيث","عندما","بينما","خلال","أيضا","أيضًا","كما","لكن","بعد","قبل","منذ","وهو","وهي","التى","اللذان","كذلك","وقد","وكان","ولكن","فيها","فيه","منها","منه","عليها","عليه","إليها","إليه","هناك","جميع","بعض","أكثر","أقل"]);
const dz="[\\u064B-\\u0652\\u0670]*";
const arW=ws=>"(?:"+ws.map(w=>[...w.replace(/[ً-ْٰ]/g,"")].map(c=>c+dz).join("")).join("|")+")";
const DEF_AR=new RegExp("^(.{2,70}?)\\s+("+arW(["هو","هي","هم","تعني","يعني","تعرف بأنها","يعرف بأنه","عبارة عن","يعد","تعد"])+")\\s+(.{12,})$","u");
const DEF_EN=/^([A-Z][^,;:()]{2,60}?)\s+(is|are|refers to|is defined as|means|is called|can be defined as)\s+(.{12,})$/;
const PRON=/^(it|this|that|they|these|those|he|she|we|there|which|هذا|هذه|ذلك|تلك|وهو|وهي|هم|هو|هي)(\s|$)/i;
function sentences(tx){
 const ab=/\b(e\.g|i\.e|et al|vs|Dr|Mr|Ms|Prof|No|Fig|etc|approx|cf|ca)\./gi;
 return String(tx||"").replace(/\[\d+\]/g,"").replace(ab,m=>m.replace(".","\u0001")).replace(/\s+/g," ")
  .replace(/([.!?؟۔])\s+/g,"$1\n").split("\n").map(s=>s.replace(/\u0001/g,".").trim()).filter(s=>s.length>=35&&s.length<=260&&/\p{L}{3}/u.test(s))}
function defn(s){let m=DEF_AR.exec(s);if(!m)m=DEF_EN.exec(s);if(!m)return null;
 const subj=m[1].replace(/\s*[\(（\[][^\)）\]]*[\)）\]]/g,"").trim();if(subj.length<2||PRON.test(subj))return null;
 return{q:isAr(subj)?"ما المقصود بـ «"+subj+"»؟":"What is “"+subj+"”?",a:m[3].replace(/[.!?؟۔]$/,"").trim()}}
const TOK=/[\p{L}\p{N}][\p{L}\p{N}'’\-]*/gu;
function pickBlank(s){const toks=[...s.matchAll(TOK)];let best=null,bs=0;
 toks.forEach((m,i)=>{const w=m[0],lw=w.toLowerCase();if(w.length<4||STOP.has(w)||STOP.has(lw)||STOP2.has(lw)||STOP2.has(w))return;
  let sc=w.length;if(/^\p{Lu}/u.test(w)&&m.index>0)sc+=8;if(/\d/.test(w))sc+=6;if(i<2)sc-=2;if(i>=toks.length-3)sc+=1;if(sc>bs){bs=sc;best=m}});
 return best}
function blankOut(s,w){let out="",last=0;for(const m of s.matchAll(TOK)){out+=s.slice(last,m.index)+(m[0]===w?"_____":m[0]);last=m.index+m[0].length}return out+s.slice(last)}
function mkCards(text,src,max){max=max||12;const out=[],seen=new Set();
 for(const s of sentences(text)){if(out.length>=max)break;const k=normT(s).slice(0,40);if(seen.has(k))continue;seen.add(k);
  const d=defn(s);if(d){out.push({id:uid(),t:"q",q:d.q,a:d.a,src});continue}
  const b=pickBlank(s);if(!b)continue;out.push({id:uid(),t:"c",q:blankOut(s,b[0]),a:b[0],src})}
 return out}
function notesToCards(text,srcName){const src={t:srcName||t("ev1"),own:1},qa=[],rest=[];
 String(text||"").split(/\r?\n/).forEach(l=>{l=l.trim();if(!l)return;
  const m=l.match(/^(?:س|Q)\s*[:：]\s*(.+?)\s*(?:ج|A)\s*[:：]\s*(.+)$/i)||l.match(/^(.+?)\s*(?:::|\t|؟\s*-\s)\s*(.+)$/);
  if(m&&m[1].length>2&&m[2].length>0)qa.push({id:uid(),t:"q",q:m[1].trim(),a:m[2].trim(),src});else rest.push(/[.!?؟۔]$/.test(l)?l:l+".")});
 return qa.concat(mkCards(rest.join(" "),src,30))}
const cardsFromPaper=p=>mkCards(p.abs||"",srcOf(p),10);

