function calc(sr,r){const s=sr?{...sr}:{e:2.5,i:0,n:0,l:0,due:0},now=Date.now();
 if(r===0){s.l++;s.n=0;s.i=0;s.e=Math.max(1.3,s.e-.2);s.due=now+6e5;return s}
 let i;if(!s.i)i=r===3?4:1;else i=Math.max(s.i+1,Math.round(s.i*(r===1?1.2:r===2?s.e:s.e*1.3)));
 if(r===1)s.e=Math.max(1.3,s.e-.15);if(r===3)s.e+=.15;
 s.n++;s.i=i;s.due=sod(now)+i*DAY;return s}
const ivLabel=s=>s.i===0?"10 "+t("sM"):(s.i<30?s.i+" "+t("sD"):Math.round(s.i/30)+" "+t("sMo"));
function newLimit(d){if(!d.exam)return 10;const days=Math.ceil((new Date(d.exam+"T00:00:00")-sod(Date.now()))/DAY);if(days<=0)return 10;
 const day=dkey(new Date()),used=d.nd&&d.nd.d===day?d.nd.n:0,unseen=d.cards.filter(c=>!c.sr).length;return Math.min(40,Math.max(3,Math.ceil((unseen+used)/days)))}
function queueFor(deckId){const now=Date.now(),day=dkey(new Date()),due=[],fresh=[];
 (deckId?S.decks.filter(d=>d.id===deckId):S.decks).forEach(d=>{let left=Math.max(0,newLimit(d)-(d.nd&&d.nd.d===day?d.nd.n:0));
  d.cards.forEach(c=>{if(!c.sr){if(left>0){fresh.push([d.id,c.id]);left--}}else if(c.sr.due<=now)due.push([d.id,c.id,c.sr.due])})});
 due.sort((a,b)=>a[2]-b[2]);return{due:due.map(x=>[x[0],x[1]]),fresh}}
const dueTotal=()=>{const q=queueFor();return q.due.length+q.fresh.length};
function deckStats(d){let n=0,due=0,mast=0;const now=Date.now();d.cards.forEach(c=>{if(!c.sr)n++;else{if(c.sr.due<=now)due++;if(c.sr.i>=21)mast++}});return{n,due,mast}}

