async function viaArchive(q){const lic='licenseurl:(*creativecommons.org* OR *publicdomain*)';const full='('+q.replace(/[():"\\]/g,' ')+') AND mediatype:texts AND '+lic;
 const j=await jf('https://archive.org/advancedsearch.php?q='+encodeURIComponent(full)+'&fl[]=identifier&fl[]=title&fl[]=creator&fl[]=year&fl[]=licenseurl&rows=8&output=json');
 return ((j.response&&j.response.docs)||[]).map(d=>({title:Array.isArray(d.title)?d.title[0]:d.title,authors:[].concat(d.creator||[]).slice(0,3),year:d.year?+d.year:null,
  url:"https://archive.org/details/"+d.identifier,license:d.licenseurl,oa:true,verified:true,src:"Internet Archive"})).filter(p=>p.title&&p.license)}
function merge(...ls){const out=[],seen=new Set();const n=Math.max(0,...ls.map(l=>l.length));
 for(let i=0;i<n;i++)for(const l of ls){const p=l[i];if(!p)continue;const k=p.doi?p.doi.toLowerCase():normT(p.title);if(seen.has(k))continue;seen.add(k);out.push(p)}
 return out}
