// --- من موضوع: ويكيبيديا + ملخصات أبحاث OpenAlex ---
async function topicGroups(q){const ar=isAr(q),yr=new Date().getFullYear(),useW=LS.get("7s_wiki",false);
 const wiki=async()=>{const j=await jf("https://"+(ar?"ar":"en")+".wikipedia.org/w/api.php?action=query&format=json&origin=*&generator=search&gsrsearch="+encodeURIComponent(q)+"&gsrlimit=2&prop=extracts%7Cinfo&exintro=1&explaintext=1&exlimit=2&inprop=url");
  const pg=Object.values((j.query&&j.query.pages)||{}).sort((a,b)=>a.index-b.index).filter(p=>p.extract);
  const out=pg.map(p=>({title:p.title+" — "+(ar?"ويكيبيديا":"Wikipedia"),authors:[],journal:"Wikipedia",year:yr,url:p.fullurl,src:"Wikipedia",abs:p.extract}));
  try{ // مراجع ويكيبيديا نفسها: روابط DOI ثم ملخصاتها من OpenAlex
   const e=await jf("https://"+(ar?"ar":"en")+".wikipedia.org/w/api.php?action=query&format=json&origin=*&prop=extlinks&elquery=doi.org&ellimit=100&titles="+encodeURIComponent(pg.map(p=>p.title).join("|")));
   const ds=[...new Set(Object.values((e.query&&e.query.pages)||{}).flatMap(p=>(p.extlinks||[]).map(l=>{const m=(l["*"]||"").match(/doi\.org\/(10\.\d{4,9}\/[^\s?#]+)/i);return m&&decodeURIComponent(m[1])})).filter(d=>d&&!/[,|]/.test(d)))].slice(0,8);
   if(ds.length){const rs=await viaOpenAlex("",{raw:"https://api.openalex.org/works?per-page=5&filter=doi:"+ds.map(encodeURIComponent).join("|")});
    rs.filter(p=>p.abs&&p.abs.length>200).slice(0,2).forEach(p=>{p.viaWiki=true;out.push(p)})}
  }catch(x){}
  return out};
 const oa=async()=>(await viaOpenAlex(keywordify(q),{oa:false,sort:"rel"})).filter(p=>p.abs&&p.abs.length>200).slice(0,3);
 const r=await Promise.allSettled(useW?[oa(),wiki()]:[oa()]);if(r.every(x=>x.status==="rejected"))throw new Error("net");
 const seen=new Set();
 return r.flatMap(x=>x.status==="fulfilled"?x.value:[]).filter(p=>{const k=keyOf(p);if(seen.has(k))return false;seen.add(k);return true}).map(p=>({p,cards:cardsFromPaper(p)})).filter(g=>g.cards.length)}
