const HELP_VIDEO="";
const HT={ar:{title:"كيف أستخدمه؟",sub:"أربع خطوات بسيطة",skip:"تخطّي",next:"التالي",start:"ابدأ",replay:"أعد الجولة",video:"شاهد الفيديو التوضيحي",back:"ابدأ الدراسة",faq:"أسئلة شائعة",
 steps:[{ic:"🃏",t:"ابنِ حزمتك من أي موضوع",d:"اكتب موضوعك في الرئيسية فيجمع التطبيق نصوصًا من ويكيبيديا وملخصات أبحاث علمية ويحوّلها إلى بطاقات. تعاين البطاقات وتحذف ما لا يعجبك قبل الحفظ. ويمكنك أيضًا لصق ملاحظاتك أو رفع ملف نصي."},
 {ic:"🧠",t:"راجع في الوقت المناسب",d:"التطبيق يجدول المراجعة تلقائيًا: ما نسيته يعود قريبًا وما أتقنته يتأخر. حدّد موعد الامتحان فيوزّع لك البطاقات الجديدة على الأيام المتبقية."},
 {ic:"🔖",t:"كل بطاقة بدليلها",d:"بعد كل إجابة يظهر مصدر البطاقة (DOI أو رابط). اضغط «اقتباس» لتأخذ المرجع بصيغة APA جاهزًا، و«المراجع» في الحزمة تعطيك قائمة مراجع كاملة لبحثك."},
 {ic:"⚔️",t:"اختبر وتحدَّ أصدقاءك",d:"العب اختبارًا بمؤقّت، ثم أرسل رابط التحدّي إلى صديق عبر واتساب أو غيره. يلعب الأسئلة نفسها ويقارن نتيجته بنتيجتك. بلا حساب ولا خادم."}],
 faqs:[["من أين تأتي البطاقات؟","من نصوص حقيقية: ملخصات الأبحاث (OpenAlex) أولًا، ومقدّمات ويكيبيديا إن فعّلتها من الرئيسية أو ملاحظاتك. يحوّلها التطبيق إلى بطاقات «ملء الفراغ» وأسئلة تعريف بقواعد لغوية بسيطة، وليس بنموذج ذكاء اصطناعي، فراجع البطاقات قبل الحفظ."],
 ["ما معنى شارة «موثّق · DOI»؟","أن البطاقة مأخوذة من ورقة علمية لها DOI يمكنك فتحها والتحقق منها. «مصدر بالرابط» يعني صفحة مرجعية، و«تمهيدي · غير محكَّم» يعني ويكيبيديا (معطّلة افتراضيًا، ولا تدخل في قائمة مراجع APA)، و«ملاحظاتي» يعني نصًا كتبته أنت."],
 ["كيف يعمل التحدّي بلا خادم؟","رابط التحدّي يحمل الأسئلة ونتيجتك داخله. عند فتحه عند صديقك يلعب الأسئلة نفسها، ثم يرسل لك رابطًا جديدًا بنتيجته. لذلك لا توجد قائمة ترتيب عالمية، بل سجل منافسين شخصي."],
 ["هل بياناتي محفوظة عند أحد؟","لا. حزمك ومصادرك ونقاطك على جهازك فقط. من «أنا ← بياناتي» يمكنك تصدير نسخة احتياطية واستيرادها على جهاز آخر."],
 ["لماذا نتائج العربية أقل من الإنجليزية؟","الفهارس العلمية العالمية تغطي العربية بدرجة أقل. ويكيبيديا العربية تعطي نتائج جيدة للمفاهيم العامة، وللأبحاث جرّب كلمات أقل أو أضف الكلمة بالإنجليزية."],
 ["كيف أثبّت التطبيق؟","على أندرويد (Chrome): اضغط «تثبيت» في الشريط العلوي أو قائمة المتصفح ثم «تثبيت التطبيق». على آيفون: افتحه في Safari ثم زر المشاركة ثم «إضافة إلى الشاشة الرئيسية». وبعد التثبيت يعمل البحث الذي سبق جلبه ودراسة حزمك بلا إنترنت."],
 ["كيف يصلني التذكير والتطبيق مغلق؟","في «أنا ← التذكيرات» اضغط «إضافة إلى التقويم»، فيذكّرك تقويم هاتفك كل أسبوع في الوقت الذي اخترته."],
 ["كيف أترجم نصًا؟","اضغط «🌐 ترجم» تحت أي نتيجة بحث، أو بطاقة دراسة بعد كشف إجابتها، أو منشور أو رسالة. يترجم التطبيق نص ذلك العنصر فقط، ويمكنك اختيار لغة الترجمة من زر 🌐 في تبويب «المجتمع». الترجمة آلية وقد تخطئ في المصطلحات، فراجعها قبل الاعتماد عليها في بحثك."],
 ["كيف أتصل بزميل صوتًا أو فيديو؟","من تبويب «المجتمع» افتح محادثة خاصة مع باحث ثم اضغط 📞 للصوت أو 🎥 للفيديو. يلزم حساب، وأن يكون التطبيق مفتوحًا عند الطرفين، وإذن الميكروفون والكاميرا. المكالمة مباشرة بين الجهازين ولا يسجّلها التطبيق، وقد لا تتصل في بعض الشبكات."]]},
 en:{title:"How do I use it?",sub:"Four simple steps",skip:"Skip",next:"Next",start:"Start",replay:"Replay the tour",video:"Watch the demo video",back:"Start studying",faq:"FAQ",
 steps:[{ic:"🃏",t:"Build a deck from any topic",d:"Type a topic on Home. The app gathers text from Wikipedia and scholarly abstracts and turns it into cards. You preview them and remove what you don't like before saving. You can also paste notes or upload a text file."},
 {ic:"🧠",t:"Review at the right time",d:"Reviews are scheduled automatically: what you forgot returns soon, what you mastered comes later. Set an exam date and the app spreads new cards over the days left."},
 {ic:"🔖",t:"Every card has its proof",d:"After each answer you see the card's source (DOI or link). Tap “Cite” for a ready APA reference, and “References” on a deck gives you the full bibliography for your paper."},
 {ic:"⚔️",t:"Quiz and challenge friends",d:"Play a timed quiz, then send the challenge link to a friend over WhatsApp or any messenger. They play the same questions and compare scores. No account, no server."}],
 faqs:[["Where do cards come from?","From real text: Wikipedia introductions, scholarly abstracts (OpenAlex) or your own notes. The app turns them into fill-in-the-blank and definition cards with simple language rules, not with an AI model, so review the cards before saving."],
 ["What does the “Cited · DOI” badge mean?","The card comes from a paper with a DOI you can open and verify. “Linked source” means a reference page, “Preliminary” means Wikipedia (off by default, not peer-reviewed, never in your APA list), and “My notes” means text you wrote yourself."],
 ["How do challenges work without a server?","The challenge link carries the questions and your score inside it. Your friend plays the same questions, then sends you a new link with their score. So there is no global leaderboard, only a personal rivals history."],
 ["Is my data stored by anyone?","No. Your decks, sources and points stay on your device only. From “Me → My data” you can export a backup and import it on another device."],
 ["Why are Arabic results fewer than English?","Global scholarly indexes cover Arabic less. Arabic Wikipedia works well for general concepts; for papers try fewer words or add the keyword in English too."],
 ["How do I install the app?","On Android (Chrome): tap “Install” in the top bar, or the browser menu then “Install app”. On iPhone: open it in Safari, tap Share, then “Add to Home Screen”. Once installed, your decks work offline."],
 ["How do I get reminders when the app is closed?","In “Me → Reminders” tap “Add to calendar”, and your phone's calendar will remind you weekly at the time you chose."],
 ["How do I translate text?","Tap “🌐 Translate” under any search result, study card (after revealing its answer), post or message. Only that item’s text is translated, and you can pick the target language with the 🌐 button in the “Community” tab. Machine translation can get terms wrong, so check it before relying on it."],
 ["How do I call a colleague by voice or video?","In the “Community” tab open a private chat with a researcher, then tap 📞 for voice or 🎥 for video. You need an account, the app open on both sides, and microphone/camera permission. Calls go directly between the two devices and are not recorded by the app; on some networks they may fail to connect."]]}};
